from fractions import Fraction

def f(x: Fraction) -> Fraction:
    return 4 * x * (1 - x)

def paired_orbits(seed: Fraction, steps: int) -> tuple[list[Fraction], list[Fraction]]:
    a, b = seed, 1 - seed
    left, right = [a], [b]
    for _ in range(steps):
        a, b = f(a), f(b)
        left.append(a); right.append(b)
    return left, right

if __name__ == "__main__":
    left, right = paired_orbits(Fraction(3, 10), 6)
    for n, pair in enumerate(zip(left, right)):
        print(n, *pair, "equal" if pair[0] == pair[1] else "different")
    assert left[1:] == right[1:]

from math import sqrt

def f(x: float) -> float:
    return 4.0 * x * (1.0 - x)

def preimages(y: float) -> tuple[float, float]:
    if not 0.0 <= y <= 1.0:
        raise ValueError("target must be in [0,1]")
    r = sqrt(1.0 - y)
    return (1.0-r)/2.0, (1.0+r)/2.0

def ancestors(y: float, depth: int) -> list[float]:
    level = [y]
    for _ in range(depth):
        level = [x for value in level for x in preimages(value)]
    return sorted(level)

if __name__ == "__main__":
    target, depth = 0.73, 4
    values = ancestors(target, depth)
    for x in values:
        image = x
        for _ in range(depth): image = f(image)
        print(f"{x:.12f} -> {image:.12f}")

from dataclasses import dataclass
from typing import Callable

@dataclass(frozen=True)
class Cycle:
    transient: int
    period: int

def update(state: int, bits: int) -> int:
    scale = 1 << bits
    return min(scale, (4*state*(scale-state) + scale//2)//scale)

def cycle(seed: int, step: Callable[[int], int]) -> Cycle:
    seen: dict[int, int] = {}
    x, n = seed, 0
    while x not in seen:
        seen[x] = n; x = step(x); n += 1
    return Cycle(seen[x], n-seen[x])

if __name__ == "__main__":
    bits = 12
    for seed in (0, 1 << (bits-1), 1234, 2345):
        print(seed, cycle(seed, lambda x: update(x, bits)))

