from math import sqrt
from typing import Iterable

def recover_ancestor(target: float, branch_bits: Iterable[int]) -> float:
    """Recover one ancestor in time linear in the branch-path length."""
    y = target
    for bit in branch_bits:
        if bit not in (0, 1): raise ValueError("branch bits must be 0 or 1")
        root = sqrt(1-y)
        y = (1-root)/2 if bit == 0 else (1+root)/2
    return y

from dataclasses import dataclass
from typing import Callable, Hashable, TypeVar
T = TypeVar("T", bound=Hashable)
@dataclass(frozen=True)
class OrbitShape:
    transient: int
    period: int

def finite_orbit_shape(seed: T, update: Callable[[T], T]) -> OrbitShape:
    first: dict[T, int] = {}; x, n = seed, 0
    while x not in first:
        first[x] = n; x = update(x); n += 1
    return OrbitShape(first[x], n-first[x])

